# -*- coding: utf-8 -*-import unittestimport numpy as npfrom src.features import MorganFeaturizerclass TestMorganFeaturizer(unittest.TestCase):    """Unit tests for SMILES-to-Morgan fingerprint NumPy conversion."""    def setUp(self):        self.n_bits = 2048        self.featurizer = MorganFeaturizer(radius=2, n_bits=self.n_bits)    def test_valid_smiles_output_shape_and_dtype(self):        """Valid SMILES (paracetamol) should return a 1D float32 binary vector."""        paracetamol = "CC(=O)NC1=CC=C(C=C1)O"        fp = self.featurizer.smiles_to_fp(paracetamol)        self.assertIsNotNone(fp)        self.assertEqual(fp.shape, (self.n_bits,))        self.assertEqual(fp.dtype, np.float32)        # Ensure values are strictly binary (0.0 or 1.0)        self.assertTrue(np.all(np.isin(fp, [0.0, 1.0])))        # Ensure at least some bits are active        self.assertGreater(np.sum(fp), 0.0)    def test_invalid_and_empty_smiles_return_none(self):        """Malformed SMILES, empty strings, and non-strings should return None."""        invalid_inputs = [            "not_a_real_molecule_123",            "C1CC",  # Unclosed ring            "",            "   ",            None,            12345,        ]        for bad_input in invalid_inputs:            with self.subTest(bad_input=bad_input):                self.assertIsNone(self.featurizer.smiles_to_fp(bad_input))    def test_batch_transform_filters_invalid_and_tracks_indices(self):        """Batch transform should drop invalid molecules and return aligned indices."""        smiles_batch = [            "CCO",                      # Index 0: Valid (Ethanol)            "INVALID_SMILES",           # Index 1: Invalid            "c1ccccc1",                 # Index 2: Valid (Benzene)            "",                         # Index 3: Invalid            "CC(=O)OC1=CC=CC=C1C(=O)O", # Index 4: Valid (Aspirin)        ]        X, valid_indices = self.featurizer.transform(smiles_batch)        self.assertEqual(X.shape, (3, self.n_bits))        self.assertEqual(X.dtype, np.float32)        self.assertEqual(valid_indices, [0, 2, 4])    def test_all_invalid_batch_returns_empty_array(self):        """A batch with zero valid SMILES should return a (0, n_bits) array."""        X, valid_indices = self.featurizer.transform(["bad_1", "bad_2"])        self.assertEqual(X.shape, (0, self.n_bits))        self.assertEqual(X.dtype, np.float32)        self.assertEqual(valid_indices, [])    def test_deterministic_output(self):        """Featurising the same molecule twice should produce identical arrays."""        caffeine = "CN1C=NC2=C1C(=O)N(C(=O)N2C)C"        fp1 = self.featurizer.smiles_to_fp(caffeine)        fp2 = self.featurizer.smiles_to_fp(caffeine)        np.testing.assert_array_equal(fp1, fp2)if __name__ == "__main__":    unittest.main(verbosity=2)